import type { ComponentPropsWithoutRef, ElementType, ReactNode } from "react";
import { cn } from "../../lib/cn";
import "../../styles/card.css";

/** Surface for grouping related content. A hairline ring instead of a heavy shadow. */
export function Card({ className, ...props }: ComponentPropsWithoutRef<"div">) {
  return <div className={cn("eui-card", className)} {...props} />;
}

export function CardHeader({ className, ...props }: ComponentPropsWithoutRef<"div">) {
  return <div className={cn("eui-card__header", className)} {...props} />;
}

export function CardTitle({
  className,
  as: Heading = "h3",
  ...props
}: ComponentPropsWithoutRef<"h3"> & { as?: ElementType }) {
  return <Heading className={cn("eui-card__title", className)} {...props} />;
}

export function CardDescription({ className, ...props }: ComponentPropsWithoutRef<"p">) {
  return <p className={cn("eui-card__description", className)} {...props} />;
}

export function CardContent({ className, ...props }: ComponentPropsWithoutRef<"div">) {
  return <div className={cn("eui-card__content", className)} {...props} />;
}

export function CardFooter({
  className,
  children,
  ...props
}: ComponentPropsWithoutRef<"div"> & { children?: ReactNode }) {
  return (
    <div className={cn("eui-card__footer", className)} {...props}>
      {children}
    </div>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Card. A hairline ring instead of a shadow, so it reads flat and calm.
   Radius is capped so a "full" radius token can't make the corners balloon. */

.eui-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
  padding: 20px;
  border-radius: min(calc(var(--eui-radius-base) * 1.5), 1rem);
  background-color: var(--eui-color-bg);
  color: var(--eui-color-fg);
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-border);
}

.eui-card__header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.eui-card__title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 24px;
  letter-spacing: -0.012em;
  color: var(--eui-color-fg);
}

.eui-card__description {
  margin: 0;
  font-size: 14px;
  line-height: 20px;
  color: var(--eui-color-fg-muted);
}

.eui-card__content {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.eui-card__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
